intrinsic_skills.content:
if event.trigger_name == "on_game_start":
	var pile = player.get_pile("deck")
	var card = game.get_card("colt_pistol", pile)
	if card == null:
		game.log("玩家游戏牌堆中没有【柯尔特手枪】牌")
		return
	player.equip(card)
elif event.trigger_name == "on_take_damage" && event.type == "hunger":
	var card = game.get_card("colt_pistol", player.hand)
	var _from_zone = false
	if card == null:
		var _eq = player.get_equipment("colt_pistol")
		if _eq != null:
			card = _eq.equipment_card
			_from_zone = true
	if card == null:
		card = game.get_card("colt_pistol", player.get_discard_pile())
	if card == null:
		game.log("玩家手牌、装备区、弃牌堆中均没有【柯尔特手枪】牌")
		return
	var pile = player.get_pile("deck")
	if _from_zone:
		await player.unequip(card)
	elif player.hand.has(card):
		player.hand.erase(card)
	else:
		player.get_discard_pile().cards.erase(card)
	pile.add(card)
	pile.shuffle()

