draw.content:
var non_empty = []
if Game.red_scavenge_pile != null and not Game.red_scavenge_pile.is_empty():
	non_empty.append(Game.red_scavenge_pile)
if Game.green_scavenge_pile != null and not Game.green_scavenge_pile.is_empty():
	non_empty.append(Game.green_scavenge_pile)
if Game.blue_scavenge_pile != null and not Game.blue_scavenge_pile.is_empty():
	non_empty.append(Game.blue_scavenge_pile)
if non_empty.is_empty():
	Game.log("所有拾荒牌堆均为空，跳过随机抓取")
else:
	var chosen = non_empty[randi() % non_empty.size()]
	await player.draw_scavenge(1, chosen)

clear.content:
for s in player.get_all_skills():
	if s.english_name == "search_corpse_draw":
		player.remove_skill(s)
		break

skills.content:
var max_steps = 2
var steps = 0
while steps < max_steps:
	var prompt = "\"骑马\": （" + str(steps + 1) + "/2）选择目标地图块"
	var _candidates = player.get_current_block().get_blocks_in_range("medium")
	var _valid = []
	for _b in _candidates:
		target = _b
		if target != player.get_current_block():
			_valid.append(_b)
		target = _b
	var _blocks = await player.choose_block_inline(_valid, prompt, 1)
	target = _blocks[0] if _blocks.size() > 0 else null
	if target == null:
		if steps == 0:
			EventSystem.cancel(event)
			return
		break
	if steps == 0:
		player.consume_action(1)
	var success = await player.move_to(target)
	if not success:
		break
	steps += 1

player.discard("horse", "equipment")
var list = game.get_all_players()
for i in list:
	i.decrease_hunger(1)

player.consume_action(1)
var weapon = player.get_equipment("revolver")
await player.consume_charge(weapon, 1)
await target.damage(3, player, "weapon_attack", weapon.equipment_card)
if player.get_charge_count("revolver") > 0:
	var _selected = await player.choose_target(1, {"filter_target_range": "medium", "filter_target": "return target != player"}, "\"左轮手枪\": 额外消耗弹药再次攻击")
	if not _selected.is_empty():
		var target2 = _selected[0]
		await player.consume_charge(weapon, 1)
		await target2.damage(3, player, "weapon_attack", weapon.equipment_card)
